<?php if(!empty($r['identity'])):?><p><strong>Returned identity:</strong> <?=e($r['identity']['name'])?><br><?=e($r['identity']['email'])?></p><p>Verified <?=e(publishing_local_time(gmdate('Y-m-d H:i:s',(int)$r['verified_at'])))?></p><?php endif;?>
<?php if($status==='pending_confirmation'):?><form method="post"><?=csrf_field()?><input type="hidden" name="account" value="<?=e($slot)?>"><input type="hidden" name="revision" value="<?=e($revision)?>"><label class="pub-choice"><input type="checkbox" required name="confirm_identity" value="1"><span>This is my requested Microsoft identity.</span></label><button class="wbtn primary" name="action" value="confirm">Confirm account</button></form><?php endif;?>
<form method="post"><?=csrf_field()?><input type="hidden" name="account" value="<?=e($slot)?>"><button class="wbtn primary" name="action" value="connect"><?=$status==='disconnected'?'Connect Microsoft 365':'Review & reconnect'?></button></form>
<?php if($status==='connected'):?>
<?php foreach(ms_features()as$key=>$feature):$granted=ms_has_scope($r['scopes']??[],$feature['scope']);?><div class="ms-feature"><div><strong><?=e($feature['name'])?></strong><br><small><?=$granted?'Read permission granted · check service':'Permission not granted'?></small></div><?php if($granted):?><form method="post"><?=csrf_field()?><input type="hidden" name="account" value="<?=e($slot)?>"><input type="hidden" name="feature" value="<?=e($key)?>"><button class="wbtn" name="action" value="read" aria-label="<?=e('Read '.$feature['name'].' for '.$account['email'])?>">Read list</button></form><?php endif;?></div><?php endforeach;?>
<?php endif;?>
<?php if($r&&($status==='connected'||!empty($r['booking_conflicts']))):?><form method="post" class="ms-conflicts"><?=csrf_field()?><input type="hidden" name="account" value="<?=e($slot)?>"><input type="hidden" name="revision" value="<?=e($revision)?>"><label class="pub-choice"><input type="checkbox" name="booking_conflicts" value="1" <?=!empty($r['booking_conflicts'])?'checked':''?>><span>Check this Outlook calendar before offering website booking slots.</span></label><p class="pub-help">Busy intervals are checked privately. If a selected calendar becomes unavailable, booking slots are held until it can be verified or you remove it from conflict checks.</p><button class="wbtn" name="action" value="conflicts">Save calendar choice</button></form><?php endif;?>
<?php if($r&&$status!=='disconnected'):?><form method="post"><?=csrf_field()?><input type="hidden" name="account" value="<?=e($slot)?>"><input type="hidden" name="revision" value="<?=e($revision)?>"><button class="pub-muted-button" name="action" value="disconnect">Remove saved access</button></form><?php endif;?>
</section><?php endforeach;?></div>
<section class="pub-card" id="agenda"><h2>Combined Outlook agenda</h2><p>Read the next seven days across confirmed Microsoft accounts. Meetings remain labelled with their source address. Each account returns up to 20 items; failed checks remain unknown.</p><form method="post"><?=csrf_field()?><button class="wbtn primary" name="action" value="agenda">Read combined agenda</button></form>
